CREATE TABLE public.ai_questionnaires (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), title text NOT NULL, purpose text NOT NULL, questions jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.ai_questionnaires TO authenticated;
GRANT ALL ON public.ai_questionnaires TO service_role;
ALTER TABLE public.ai_questionnaires ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Questionnaire owner or admin" ON public.ai_questionnaires FOR ALL TO authenticated USING (owner_id=auth.uid() OR public.has_role(auth.uid(),'admin')) WITH CHECK (owner_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.validate_questionnaire() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE q jsonb; BEGIN IF jsonb_typeof(new.questions)<>'array' OR jsonb_array_length(new.questions)<1 OR jsonb_array_length(new.questions)>20 THEN RAISE EXCEPTION 'שאלון חייב להכיל בין שאלה אחת ל־20 שאלות'; END IF; FOR q IN SELECT value FROM jsonb_array_elements(new.questions) LOOP IF jsonb_typeof(q)<>'object' OR jsonb_typeof(q->'label')<>'string' OR length(q->>'label') NOT BETWEEN 1 AND 300 OR (q->>'label') ~* '<[[:space:]]*[/!?a-z]|(javascript|vbscript)[[:space:]]*:' OR q->>'kind' NOT IN ('text','yes_no') THEN RAISE EXCEPTION 'שאלה אינה תקינה'; END IF; END LOOP; RETURN new; END $$;
CREATE TRIGGER questionnaire_shape BEFORE INSERT OR UPDATE ON public.ai_questionnaires FOR EACH ROW EXECUTE FUNCTION public.validate_questionnaire();
CREATE TRIGGER questionnaire_text BEFORE INSERT OR UPDATE ON public.ai_questionnaires FOR EACH ROW EXECUTE FUNCTION public.validate_application_text();
CREATE TABLE public.community_credit_ledger (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), amount integer NOT NULL CHECK(amount<>0), reason text NOT NULL, actor_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), request_id uuid NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.community_credit_ledger TO authenticated;
GRANT ALL ON public.community_credit_ledger TO service_role;
ALTER TABLE public.community_credit_ledger ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own or admin ledger" ON public.community_credit_ledger FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TRIGGER ledger_text BEFORE INSERT ON public.community_credit_ledger FOR EACH ROW EXECUTE FUNCTION public.validate_application_text();
CREATE FUNCTION public.adjust_community_credit(target_user uuid, delta integer, explanation text, operation_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; balance bigint; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'גישה למנהלת בלבד' USING ERRCODE='42501'; END IF; IF delta=0 OR abs(delta::bigint)>100000 OR length(trim(explanation)) NOT BETWEEN 1 AND 300 THEN RAISE EXCEPTION 'סכום או נימוק אינם תקינים'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(target_user::text,0)); SELECT id INTO result FROM public.community_credit_ledger WHERE request_id=operation_id; IF result IS NOT NULL THEN RETURN result; END IF; SELECT coalesce(sum(amount),0) INTO balance FROM public.community_credit_ledger WHERE user_id=target_user; IF balance+delta<0 THEN RAISE EXCEPTION 'היתרה אינה מספיקה לחיוב'; END IF; INSERT INTO public.community_credit_ledger(user_id,amount,reason,actor_id,request_id) VALUES(target_user,delta,trim(explanation),auth.uid(),operation_id) RETURNING id INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.adjust_community_credit(uuid,integer,text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.adjust_community_credit(uuid,integer,text,uuid) TO authenticated;
CREATE TABLE public.community_activity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), activity_day date NOT NULL DEFAULT (now() AT TIME ZONE 'Asia/Jerusalem')::date, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,activity_day));
GRANT SELECT, INSERT ON public.community_activity TO authenticated;
GRANT ALL ON public.community_activity TO service_role;
ALTER TABLE public.community_activity ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Record own activity" ON public.community_activity FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND activity_day=(now() AT TIME ZONE 'Asia/Jerusalem')::date);
CREATE POLICY "Admin activity read" ON public.community_activity FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.comment_moderation_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), outcome text NOT NULL CHECK(outcome IN ('allowed','blocked','unavailable')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.comment_moderation_events TO authenticated;
GRANT ALL ON public.comment_moderation_events TO service_role;
ALTER TABLE public.comment_moderation_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admin moderation counts" ON public.comment_moderation_events FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
GRANT INSERT, UPDATE, DELETE ON public.blocked_words TO authenticated;
GRANT INSERT, UPDATE, DELETE ON public.announcements TO authenticated;
ALTER TABLE public.nail_trade_items ALTER COLUMN status SET DEFAULT 'pending';
CREATE FUNCTION public.guard_trade_approval() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN IF TG_OP='INSERT' THEN new.status:='pending'; ELSIF new.status IS DISTINCT FROM old.status THEN RAISE EXCEPTION 'שינוי אישור מודעה מותר למנהלת בלבד' USING ERRCODE='42501'; END IF; END IF; RETURN new; END $$;
CREATE TRIGGER trade_approval BEFORE INSERT OR UPDATE ON public.nail_trade_items FOR EACH ROW EXECUTE FUNCTION public.guard_trade_approval();
CREATE POLICY "Admin trade approval" ON public.nail_trade_items FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
REVOKE INSERT ON public.post_comments FROM authenticated;
CREATE FUNCTION public.guard_comment_author() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.user_sanctions WHERE user_id=new.user_id AND (until IS NULL OR until>now())) THEN RAISE EXCEPTION 'החשבון מושהה ולא ניתן להגיב'; END IF; RETURN new; END $$;
CREATE TRIGGER comment_author_rules BEFORE INSERT ON public.post_comments FOR EACH ROW EXECUTE FUNCTION public.guard_comment_author();